#!/bin/sh

# Asserts that the sudo rules generated by hb_write_sudoers grant the Homebridge
# UI exactly the privileged commands it needs, and nothing else.
#
# Usage: ./test/test-sudo-scope.sh [image] [platform]
#
#   image     image to test, defaults to docker-homebridge
#   platform  --platform value to pass to docker run, e.g. linux/amd64

set -e

IMAGE="${1:-docker-homebridge}"
PLATFORM_ARG=""
[ -n "$2" ] && PLATFORM_ARG="--platform $2"

# shellcheck disable=SC2086
docker run --rm $PLATFORM_ARG --entrypoint bash "$IMAGE" -c '
set -e

HB_SERVICE_USER=homebridge
HB_SERVICE_UID=1000
HB_SERVICE_GID=1000
. /etc/s6-overlay/scripts/service-user.sh
HB_SERVICE_USER=homebridge
HB_SERVICE_UID=1000
HB_SERVICE_GID=1000

groupmod -o -g 1000 homebridge > /dev/null 2>&1 || groupadd -o -g 1000 homebridge
usermod -o -u 1000 -g homebridge homebridge > /dev/null 2>&1 || useradd -o -u 1000 -g homebridge homebridge
# a second account sharing the uid, to exercise the "#1000" rule - this is the
# case the by-name rule does not cover, e.g. Ubuntu 24.04 where uid 1000 is
# already taken by the "ubuntu" user
useradd -o -u 1000 -g homebridge -M -s /bin/sh uidtwin > /dev/null 2>&1 || true

FAILED=0

check() {
  EXPECT="$1"; AS="$2"; shift 2
  if sudo -u "$AS" -n sudo -n -l "$@" > /dev/null 2>&1; then GOT=allow; else GOT=deny; fi
  if [ "$GOT" = "$EXPECT" ]; then
    printf "  ok    %-6s %-8s sudo %s\n" "$EXPECT" "$AS" "$*"
  else
    printf "  FAIL  want=%-6s got=%-6s %-8s sudo %s\n" "$EXPECT" "$GOT" "$AS" "$*"
    FAILED=$((FAILED + 1))
  fi
}

run_matrix() {
  AS="$1"
  check allow "$AS" /usr/bin/kill 1
  check allow "$AS" /usr/bin/kill -9 4242
  check allow "$AS" /usr/bin/apt-get update
  check allow "$AS" /usr/bin/apt-get install --only-upgrade -y homebridge
  check allow "$AS" /usr/sbin/shutdown -r now
  check allow "$AS" /usr/sbin/shutdown -h now
  check deny  "$AS" /bin/bash -c id
  check deny  "$AS" /bin/sh -c id
  check deny  "$AS" /usr/bin/apt-get install -y netcat
  check deny  "$AS" /usr/bin/apt-get remove -y homebridge
  check deny  "$AS" /opt/homebridge/bin/npm install -g anything
  check deny  "$AS" /usr/bin/tee /etc/sudoers
  check deny  "$AS" /usr/bin/chown root:root /homebridge/startup.sh
  check deny  "$AS" /usr/bin/visudo
}

echo "== restricted rules (default) =="
unset HB_SUDO_UNRESTRICTED
hb_write_sudoers
visudo -cf /etc/sudoers.d/010_homebridge-nopasswd > /dev/null
echo "  ok    sudoers file passes visudo -c"
echo "-- by name (homebridge) --"
run_matrix homebridge
echo "-- by uid (#1000, account name not in sudoers) --"
run_matrix uidtwin

echo "== escape hatch: HB_SUDO_UNRESTRICTED=1 =="
HB_SUDO_UNRESTRICTED=1 hb_write_sudoers > /dev/null
check allow homebridge /bin/bash -c id

echo
if [ "$FAILED" -ne 0 ]; then
  echo "FAILED: $FAILED assertion(s)"
  exit 1
fi
echo "PASSED: sudo scope is as expected"
'
